from pathlib import Path
import re,json,hashlib
m=Path('../../step-00-input/scenario-set-round-0.json')
paths={r:m.parent/p for r,p in json.loads(m.read_text()).items()}
source={r:p.read_text() for r,p in paths.items()}
# Read the complete source documents into memory; no intermediate files.
report=Path('../round-1/coverage-round-1.md').read_text()
source_us=Path('../../../../docs/case-study-source.md').read_text()
ac={}
for l in source_us.splitlines():
 if l.startswith('| US-'): ac[l.split('|')[1].strip()]=l.split('|')[-2].strip()
for r,t in source.items():
 print(r,len(t),'characters',len(re.findall(r'"'^## TS-US-'"',t,re.M)),'definitions',hashlib.sha256(t.encode()).hexdigest()[:16])
 print('MAPPINGS', '\\n'.join(dict.fromkeys(l for l in t.splitlines() if l.startswith('- FR / Flow / Screen:'))))
print('feedback read',len(report),'characters')
print('fixture reserved IDs',sorted(set(re.findall(r'TS-US-\\d+-\\d+',Path('../../../input/ui-scenarios.json').read_text()))))
PY"

